def fitK(fT):
    # linear in c1,c2,c3 for given t-factor and K grid
    bestl=(np.inf,None)
    for K in np.linspace(3,12,91):
        X=np.column_stack([1/P,np.log(1+P)**2,fT*P*(1-P/K)])
        c=np.linalg.lstsq(X,y,rcond=None)[0]
        e=np.mean((y-X@c)**2)/np.var(y)
        if e<bestl[0]: bestl=(e,K,c)
    return bestl
